295: interface StreamingMarkdownErrorBoundaryProps {
296:   content: string;
297:   children: React.ReactNode;
298:   isStreaming: boolean;
299: }
300: 
301: // Sometimes remark will throw errors, particularly when rendering math. We add
302: // this fallback to show the plain text content if there's an error, and then we
303: // retry rendering the content if the content changes OR if we change our
304: // streaming state (because we render things differently when in streaming mode
305: // v. not, so for some cases we'll automatically recover once streaming is over)
306: //
307: // This should not be relied on for anything known to be broken (any known
308: // errors should be fixed!), but it's necessary to not break the full UI because
309: // of some bad markdown
310: class StreamingMarkdownErrorBoundary extends React.Component<
311:   StreamingMarkdownErrorBoundaryProps,
312:   { hasError: boolean }
313: > {
314:   constructor(props: StreamingMarkdownErrorBoundaryProps) {
315:     super(props);
316:     this.state = { hasError: false };
317:   }
318: 
319:   componentDidUpdate(prevProps: StreamingMarkdownErrorBoundaryProps) {
320:     if (
321:       prevProps.isStreaming !== this.props.isStreaming ||
322:       prevProps.content !== this.props.content
323:     ) {
324:       this.setState({ hasError: false });
325:     }
326:   }
327: 
328:   static getDerivedStateFromError(/*_error: Error*/) {
329:     return { hasError: true };
330:   }
331: 
332:   componentDidCatch(error: Error, info: { componentStack: string }) {
333:     console.error(
334:       "StreamingMarkdownContent: caught rendering error",
335:       error,
336:       info,
337:     );
338:   }
339: 
340:   render() {
341:     if (this.state.hasError) {
342:       // TODO(drifkin): render this more nicely so it's not so jarring. For
343:       // example, probably want to render newlines, etc. But let's not get too
344:       // fancy because then we'll end up needing an ErrorBoundaryErrorBoundary
345:       // :upside_down_face:
346:       return <div>{this.props.content}</div>;
347:     }
348: 
349:     return this.props.children;
350:   }
351: }
352: 
353: export default StreamingMarkdownContent;
